import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';

/**
 * Create an invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }> }} input
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }> } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return customerResult;

  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  const customer = customerResult.value;
  const tierDiscount = TIER_DISCOUNTS[customer.tier];

  const enrichedLines = [];
  for (const line of lines) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    const discountValidation = validateDiscount(line.discountPercent);
    if (!discountValidation.ok) return discountValidation;

    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    const enrichedLine = {
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };
    const effectiveDiscount = line.discountPercent !== undefined ? line.discountPercent : tierDiscount;
    if (effectiveDiscount > 0) {
      enrichedLine.discountPercent = effectiveDiscount;
    }
    enrichedLines.push(enrichedLine);
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: enrichedLines,
  });
}

/**
 * Calculate the total for a single invoice line.
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount for a single invoice line.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number}
 */
export function lineDiscount(line) {
  if (!line.discountPercent) return 0;
  return Math.max(0, roundCents(lineTotal(line) * line.discountPercent / 100));
}

/**
 * Calculate subtotal, discount, and total for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number }> }} invoice
 * @returns {{ subtotal: number, discount: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const total = Math.max(0, subtotal - discount);
  return { subtotal, discount, total };
}

/**
 * Add a line to a draft invoice, or increase qty if SKU already exists.
 * @param {{ status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }> }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} line
 * @returns {{ ok: true, value: { status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }> } } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  const discountValidation = validateDiscount(discountPercent);
  if (!discountValidation.ok) return discountValidation;

  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingLineIndex !== -1) {
    newLines[existingLineIndex].qty += qty;
    if (discountPercent !== undefined) {
      newLines[existingLineIndex].discountPercent = discountPercent;
    }
  } else {
    const newLine = {
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };
    if (discountPercent !== undefined) {
      newLine.discountPercent = discountPercent;
    }
    newLines.push(newLine);
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from a draft invoice by SKU.
 * @param {{ status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }> }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: { status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }> } } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex === -1) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((line) => line.sku !== sku);
  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a number and changing status to 'issued'.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }> }} invoice
 * @param {string[]} existingNumbers - Array of invoice numbers already used
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, number: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }> } } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);
  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

function validateDiscount(discountPercent) {
  if (discountPercent === undefined || discountPercent === null) return ok();
  if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
    return fail('DISCOUNT_INVALID');
  }
  return ok();
}

function isValidDate(dateStr) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) return false;
  const date = new Date(dateStr + 'T00:00:00Z');
  const parts = dateStr.split('-');
  return (
    date instanceof Date &&
    !isNaN(date) &&
    date.getUTCFullYear() === parseInt(parts[0], 10) &&
    date.getUTCMonth() === parseInt(parts[1], 10) - 1 &&
    date.getUTCDate() === parseInt(parts[2], 10)
  );
}

